#!/usr/bin/env node
// Rasterise every explainer SVG in dist/diagrams/ to PNGs for Google Images + OG.
//
// Runs AFTER `astro build`, over dist/diagrams/, so it catches BOTH static diagrams
// (public/diagrams/*.svg copied to dist) and data-driven ones generated by Astro
// endpoints (src/pages/diagrams/*.svg.ts). For each <name>.svg it writes:
//   <name>.png     — 2× on-page raster (indexable <img> fallback + ImageObject)
//   <name>.og.png  — 1200×630 social/OG card (diagram centred on white)
// Google Images indexes raster reliably but SVG poorly; the SVG stays the crisp
// on-page <source> and the source of truth. PNGs are build output (dist/, not committed).

import sharp from "sharp";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";

const DIR = process.argv[2] || "dist/diagrams";
if (!existsSync(DIR)) {
  process.stdout.write(`No ${DIR}/ — nothing to rasterise.\n`);
  process.exit(0);
}

const OG_W = 1200;
const OG_H = 630;

// Walk recursively so per-field/per-page diagrams in subfolders (e.g.
// diagrams/valdkond/<slug>.svg from an Astro endpoint) are rasterised too.
function svgFiles(dir) {
  const out = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...svgFiles(full));
    else if (entry.name.endsWith(".svg")) out.push(full);
  }
  return out;
}

let count = 0;
for (const svgPath of svgFiles(DIR)) {
  const svg = readFileSync(svgPath);
  const base = svgPath.replace(/\.svg$/, "");

  // On-page raster: 2× the SVG's intrinsic size (density 144 = 72×2).
  await sharp(svg, { density: 144 })
    .flatten({ background: "#ffffff" })
    .png({ compressionLevel: 9 })
    .toFile(`${base}.png`);

  // OG card: render the diagram to fit within a padded 1200×630 white canvas.
  const inner = await sharp(svg, { density: 180 })
    .resize(1120, 588, { fit: "inside", background: "#ffffff" })
    .png()
    .toBuffer();
  await sharp({ create: { width: OG_W, height: OG_H, channels: 4, background: "#ffffff" } })
    .composite([{ input: inner, gravity: "center" }])
    .png({ compressionLevel: 9 })
    .toFile(`${base}.og.png`);

  count += 1;
  process.stdout.write(`rasterised ${path.relative(DIR, svgPath)} → .png + .og.png\n`);
}
process.stdout.write(`Done: ${count} diagram(s).\n`);
